import type { ScriptContext, ScriptResult } from "@gtm-factory/core";

/** Reads the reply and our message; answers interested or not. */
export default function run(ctx: ScriptContext): ScriptResult {
  const reply = ctx.get("reply_received");
  const llm = ctx.get("llm_completion");
  ctx.get("rating");
  const r = ctx.vendor.call("llm.judge", { reply: reply.id, model: llm.content.model, question: "Is this person interested?" });
  return r.ok ? { content: { verdict: "interested" } } : null;
}

import type { ScriptContext, ScriptResult } from "@gtm-factory/core";

/** The client's CRM reports each lead it marked interested. Called by another party: it reports, it is never ordered. */
export default function run(ctx: ScriptContext): ScriptResult {
  const r = ctx.vendor.call("webhook.report");
  return r.ok ? { content: {} } : null;
}

import type { ScriptContext, ScriptResult } from "@gtm-factory/core";

/** A lead finds the brand on their own. Called by another party: it reports, it is never ordered. */
export default function run(ctx: ScriptContext): ScriptResult {
  const r = ctx.vendor.call("webhook.report");
  return r.ok ? { content: {} } : null;
}

import type { ScriptContext, ScriptResult } from "@gtm-factory/core";

/** The client's website: a visitor signs up or books a demo. */
export default function run(ctx: ScriptContext): ScriptResult {
  ctx.get("lead_visited");
  ctx.get("rating");
  const r = ctx.vendor.call("website.form");
  return r.ok ? { content: { form: "signup" } } : null;
}

import type { ScriptContext, ScriptResult } from "@gtm-factory/core";

/** Reads the reply and asks the LLM completion it orders whether the person is interested: an answer opening on "no" is not. */
export default function run(ctx: ScriptContext): ScriptResult {
  const reply = ctx.get("reply_received");
  ctx.ask({ prompt: `Someone answered our message. Their answer:\n${String(reply.content.text ?? "")}\n\nIs this person interested? Answer yes or no.` });
  const llm = ctx.get("llm_completion");
  ctx.get("rating");
  if (/^\s*no\b/i.test(String(llm.content.text ?? ""))) return null;
  return { content: { verdict: "interested" } };
}
